def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < n:
                if line[i] == '"':
                    # Check if it's a doubled quote or end of quoted field
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows
                        if i < n:
                            if line[i] == ',':
                                i += 1
                            else:
                                return None
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
            fields.append(field)
        else:
            # Unquoted field
            field = ""
            while i < n and line[i] != ',':
                if line[i] == '"':
                    return None
                field += line[i]
                i += 1
            fields.append(field)
            if i < n:
                i += 1  # Skip the comma

    return fields

